cases.bad:
// onTabUpdated loading — only resets download guard
if (changeInfo.status === 'loading') {
  this.autoDownloadedTabs.delete(tabId);
  // Media NOT cleared — comment: "persists across navigation until tab closed"
}
// onTabRemoved has clearTab + clearSessionMedia + lastCuesByTab.delete + updateBadgeForTab
// but onTabUpdated does not reuse them → media doubles each episode

cases.good:
// onTabUpdated loading — reuse the same clear methods as onTabRemoved
if (changeInfo.status === 'loading') {
  this.autoDownloadedTabs.delete(tabId);
  this.networkInterceptor.clearTab(tabId);
  this.clearSessionMedia(tabId);
  this.lastCuesByTab.delete(tabId);
  this.updateBadgeForTab(tabId);
}

